1	using System.Diagnostics;
2	using System.Text;
3	using QBrainAi.Common.AgentCli;
4	using QBrainAi.Support.Mcp.Services;
5	using QBrainAi.Support.Mcp.Storage.Entities;
6	using Microsoft.Extensions.Configuration;
7	using Microsoft.Extensions.Logging.Abstractions;
8	using Microsoft.Extensions.Options;
9	using QBrainAi.Support.Mcp.Tests.TestSupport;
10	using Xunit;
11	
12	namespace QBrainAi.Support.Mcp.Tests.Services;
13	
14	/// <summary>
15	/// TEST-MCP-QBCLI-001: QuadBrain CLI provider kind, persistent Grok/Codex session args, and slot session reuse. The
16	/// class runs in <see cref="ProcessEnvironmentCollection"/> because its temp-folder tests write the process environment
17	/// through <c>WithIsolatedQuadbrainTemp</c>; those tests are integration tests (TR-MCP-USECASE-018 AC-006,
18	/// TR-MCP-USECASE-019 AC-008; the sweep of plan section 19.3).
19	/// </summary>
20	[Collection(ProcessEnvironmentCollection.Name)]
21	public sealed class CliBrainSlotStrategyTests
22	{
23	    private static readonly SemaphoreSlim TempEnvLock = new(1, 1);
24	
25	    [Theory]
26	    [InlineData("Cli")]
27	    [InlineData("cli")]
28	    public void NormalizeProviderKind_AcceptsCli(string kind)
29	    {
30	        Assert.Equal("Cli", BrainSlotValidation.NormalizeProviderKind(kind));
31	    }
32	
33	    [Theory]
34	    [InlineData("cli://grok-cli", "grok-cli")]
35	    [InlineData("cli://grok-build", "grok-cli")]
36	    [InlineData("cli://codex-cli", "codex-cli")]
37	    public void TryParseCliEndpoint_KnownStrategies_Succeed(string endpoint, string expected)
38	    {
39	        Assert.True(CliBrainSlotEndpoint.TryParse(endpoint, out var strategy));
40	        Assert.Equal(expected, strategy);
41	    }
42	
43	    [Theory]
44	    [InlineData("http://127.0.0.1:8311/v1")]
45	    [InlineData("cli://unknown")]
46	    [InlineData("")]
47	    public void TryParseCliEndpoint_Unknown_Fails(string endpoint)
48	    {
49	        Assert.False(CliBrainSlotEndpoint.TryParse(endpoint, out _));
50	    }
51	
52	    [Fact]
53	    public void ValidateEndpoint_CliKnownStrategy_DoesNotRequireHttpHostAllowlist()
54	    {
55	        var options = new StaticOptionsMonitor<BrainSlotOptions>(new BrainSlotOptions
56	        {
57	            AllowLoopbackEndpoints = false,
58	            AllowedEndpointHosts = [],
59	        });
60	
61	        var exception = Record.Exception(() =>
62	            BrainSlotValidation.ValidateEndpoint("Cli", "cli://grok-cli", options));
63	
64	        Assert.Null(exception);
65	    }
66	
67	    [Fact]
68	    public void ValidateEndpoint_CliUnknownStrategy_Throws()
69	    {
70	        var options = new StaticOptionsMonitor<BrainSlotOptions>(new BrainSlotOptions());
71	
72	        var ex = Assert.Throws<BrainSlotValidationException>(() =>
73	            BrainSlotValidation.ValidateEndpoint("Cli", "cli://copilot-cli", options));
74	
75	        Assert.Equal(BrainSlotReasonCodes.EndpointNotAllowed, ex.Reason);
76	    }
77	
78	    [Fact]
79	    public void BuildPersistentGrokArgumentList_FirstTurn_UsesSessionIdAndXhigh()
80	    {
81	        var sessionId = Guid.Parse("aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee").ToString();
82	        var args = GrokCliAgentExecutionStrategy.BuildPersistentGrokArgumentList(
83	            workingDirectory: @"Q:\__mcp_unit_test__\QBrainAi",
84	            promptFilePath: @"C:\temp\grok-prompt.txt",
85	            model: "grok-4.6",
86	            sessionId: sessionId,
87	            resume: false);
88	
89	        Assert.Contains("--effort", args);
90	        Assert.Equal("xhigh", args[args.ToList().IndexOf("--effort") + 1]);
91	        Assert.Contains("--reasoning-effort", args);
92	        Assert.Equal("xhigh", args[args.ToList().IndexOf("--reasoning-effort") + 1]);
93	        Assert.Contains("--model", args);
94	        Assert.Contains("grok-4.6", args);
95	        Assert.Contains("--session-id", args);
96	        Assert.Contains(sessionId, args);
97	        Assert.DoesNotContain("--resume", args);
98	        Assert.Contains("--always-approve", args);
99	        Assert.DoesNotContain("plan", args);
100	        Assert.Contains("--no-plan", args);
101	        Assert.Contains("--max-turns", args);
102	        Assert.Equal("1", args[args.ToList().IndexOf("--max-turns") + 1]);
103	        Assert.Contains("--no-subagents", args);
104	        Assert.Contains("--verbatim", args);
105	    }
106	
107	    [Fact]
108	    public void BuildPersistentGrokArgumentList_Resume_UsesResumeFlag()
109	    {
110	        var sessionId = Guid.Parse("aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee").ToString();
111	        var args = GrokCliAgentExecutionStrategy.BuildPersistentGrokArgumentList(
112	            workingDirectory: @"Q:\__mcp_unit_test__\QBrainAi",
113	            promptFilePath: @"C:\temp\grok-prompt.txt",
114	            model: "grok-4.6",
115	            sessionId: sessionId,
116	            resume: true);
117	
118	        Assert.Contains("--resume", args);
119	        Assert.Contains(sessionId, args);
120	        Assert.DoesNotContain("--session-id", args);
121	    }
122	
123	    /// <summary>
124	    /// TEST-MCP-QBCLI-001: Grok runs in an isolated working folder with its dashboard, memory and subagents off and
