27	/// <summary>
28	/// Default <see cref="IAgentStdioProtocol"/> implementation. Accumulates inbound lines into
29	/// YAML documents using the blank-line and <c>---</c> conventions, delegates parsing to
30	/// <see cref="IYamlSerializer"/>, and routes each envelope through
31	/// <see cref="IReplCommandDispatcher"/>. Malformed documents are reported as
32	/// <c>invalid_envelope</c> errors and the loop continues.
33	/// </summary>
34	public sealed class AgentStdioProtocol : IAgentStdioProtocol
35	{
36	    private const string CommandTimeoutEnvVar = "MCPSERVER_REPL_COMMAND_TIMEOUT_SECONDS";
37	
38	    private readonly IYamlSerializer _serializer;
39	    private readonly IReplCommandDispatcher _dispatcher;
40	
41	    /// <summary>
42	    /// Initializes a new <see cref="AgentStdioProtocol"/>.
43	    /// </summary>
44	    /// <param name="serializer">YAML serializer used to parse and emit envelopes.</param>
45	    /// <param name="dispatcher">Command dispatcher invoked once per complete inbound envelope.</param>
46	    public AgentStdioProtocol(IYamlSerializer serializer, IReplCommandDispatcher dispatcher)
47	    {
48	        _serializer = serializer ?? throw new ArgumentNullException(nameof(serializer));
49	        _dispatcher = dispatcher ?? throw new ArgumentNullException(nameof(dispatcher));
50	    }
51	
52	    /// <inheritdoc />
53	    public async Task RunAsync(TextReader reader, TextWriter writer, CancellationToken cancellationToken)
54	    {
55	        ArgumentNullException.ThrowIfNull(reader);
56	        ArgumentNullException.ThrowIfNull(writer);
57	
58	        var buffer = new StringBuilder();
59	
60	        while (!cancellationToken.IsCancellationRequested)
61	        {
62	            var line = await reader.ReadLineAsync(cancellationToken).ConfigureAwait(false);
63	            if (line is null)
64	            {
65	                // End of stream — flush any accumulated envelope before exiting.
66	                await FlushAsync(buffer, writer, cancellationToken).ConfigureAwait(false);
67	                return;
68	            }
69	
70	            if (IsDocumentBoundary(line))
71	            {
72	                await FlushAsync(buffer, writer, cancellationToken).ConfigureAwait(false);
73	                continue;
74	            }
75	
76	            // FR-MCP-REPL-005: NDJSON fast path - a complete single-line JSON
77	            // envelope is a full document; dispatch it immediately instead of
78	            // waiting for a blank-line/--- boundary. This makes persistent
79	            // bridge clients that write one JSON line per request first-class.
80	            if (buffer.Length == 0 && IsCompleteSingleLineJson(line))
81	            {
82	                buffer.AppendLine(line);
83	                await FlushAsync(buffer, writer, cancellationToken).ConfigureAwait(false);
84	                continue;
85	            }
86	
87	            buffer.AppendLine(line);
88	        }
89	
90	        // Cancellation requested — attempt a final flush so callers don't lose the last envelope.
91	        await FlushAsync(buffer, writer, cancellationToken).ConfigureAwait(false);
92	    }
93	
94	    private static bool IsDocumentBoundary(string line)
95	    {
96	        if (string.IsNullOrWhiteSpace(line))
97	        {
98	            return true;
99	        }
100	
101	        var trimmed = line.TrimEnd();
102	        return trimmed == "---";
103	    }
104	
105	    private static bool IsCompleteSingleLineJson(string line)
106	    {
107	        var trimmed = line.Trim();
108	        if (trimmed.Length < 2 || trimmed[0] != '{' || trimmed[^1] != '}')
109	        {
110	            return false;
111	        }
112	
113	        try
114	        {
115	            using var _ = System.Text.Json.JsonDocument.Parse(trimmed);
116	            return true;
117	        }
118	        catch (System.Text.Json.JsonException)
119	        {
120	            return false;
121	        }
122	    }
123	
124	    private async Task FlushAsync(StringBuilder buffer, TextWriter writer, CancellationToken cancellationToken)
125	    {
126	        if (buffer.Length == 0)
127	        {
128	            return;
129	        }
130	
131	        var document = buffer.ToString();
132	        buffer.Clear();
133	
134	        if (string.IsNullOrWhiteSpace(document))
135	        {
136	            return;
137	        }
138	
139	        IYamlEnvelope envelope;
140	        try
141	        {
142	            envelope = _serializer.Deserialize(document);
143	        }
144	        catch (Exception ex) when (ex is FormatException or InvalidOperationException)
145	        {
146	            var errorEnvelope = new YamlEnvelope
147	            {
148	                Type = "error",
149	                Payload = new ErrorPayload
150	                {
151	                    RequestId = TryExtractRequestId(document),
152	                    Code = "invalid_envelope",
153	                    Message = ex.Message,
