157	            return;
158	        }
159	
160	        IYamlEnvelope response;
161	        // TR-MCP-REPL-001 AC-002: the configured timeout is read once and only a valid value is used, so the
162	        // timeout message names the timeout that applied and a misconfigured value never fails the request.
163	        var commandTimeout = ReplCommandTimeout.FromEnvironment(CommandTimeoutEnvVar);
164	        using var commandCts = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
165	        commandCts.CancelAfter(commandTimeout);
166	
167	        try
168	        {
169	            if (_dispatcher is IStreamingReplCommandDispatcher streamingDispatcher)
170	            {
171	                response = await streamingDispatcher.DispatchAsync(
172	                    envelope,
173	                    async evt => await WriteEnvelopeAsync(evt, writer, cancellationToken).ConfigureAwait(false),
174	                    commandCts.Token).ConfigureAwait(false);
175	            }
176	            else
177	            {
178	                response = await _dispatcher.DispatchAsync(envelope, commandCts.Token).ConfigureAwait(false);
